    res = converter.convert(f)
    doc = res.document

    # Recursive labels
    rec_labels = []
    visited = set()
    def traverse(cref):
        if cref in visited:
            return
        visited.add(cref)
        obj = resolve_ref(doc, cref)
        label = getattr(obj, 'label', None)
        if label is not None:
            rec_labels.append(str(label.value if hasattr(label, 'value') else label))
