import glob, os, re
from docling.document_converter import DocumentConverter

converter = DocumentConverter()
files = sorted(glob.glob('corpus/*.md') + glob.glob('corpus/*.html'))

def resolve_ref(doc, cref):
    parts = cref[2:].split('/')
    obj = doc
    for part in parts:
        if part.isdigit():
            obj = obj[int(part)]
        else:
            obj = getattr(obj, part)
    return obj

for f in files:
    print('=== File:', f)
    res = converter.convert(f)
    doc = res.document

    # Method A: Recursive traversal of children (no filtering of content layer)
    counts_a = {}
    max_depth_a = 0
    visited_a = set()
    def traverse_a(cref, depth):
        if cref in visited_a:
            return
        visited_a.add(cref)
        obj = resolve_ref(doc, cref)
        label = getattr(obj, 'label', None)
        if label is not None:
            lbl_str = str(label.value if hasattr(label, 'value') else label)
            lbl_norm = re.sub(r'[^a-z0-9]', '_', lbl_str.lower())
            counts_a[lbl_norm] = counts_a.get(lbl_norm, 0) + 1
        global max_depth_a
        if depth > max_depth_a:
            max_depth_a = depth
        if hasattr(obj, 'children') and obj.children:
            for child in obj.children:
                traverse_a(child.cref, depth + 1)

    for child in doc.body.children:
        traverse_a(child.cref, 1)

    print('Method A - Max Depth:', max_depth_a, 'Counts:', counts_a)

    # Method B: doc.iterate_items(doc.body, with_groups=True)
    counts_b = {}
    max_depth_b = 0
    for item, depth in doc.iterate_items(doc.body, with_groups=True):
        if item.self_ref == '#/body':
            continue  # skip body root itself
        label = getattr(item, 'label', None)
        if label is not None:
            lbl_str = str(label.value if hasattr(label, 'value') else label)
            lbl_norm = re.sub(r'[^a-z0-9]', '_', lbl_str.lower())
            counts_b[lbl_norm] = counts_b.get(lbl_norm, 0) + 1
        if depth > max_depth_b:
            max_depth_b = depth

    print('Method B - Max Depth:', max_depth_b, 'Counts:', counts_b)
"

