import glob, os
from docling.document_converter import DocumentConverter

converter = DocumentConverter()
files = sorted(glob.glob('corpus/*.md') + glob.glob('corpus/*.html'))

def resolve_ref(doc, cref):
    parts = cref[2:].split('/')
    obj = doc
    for part in parts:
        if part.isdigit():
            obj = obj[int(part)]
        else:
            obj = getattr(obj, part)
    return obj

for f in files:
    res = converter.convert(f)
    doc = res.document
    visited = set()
    layers = set()
    def traverse(cref):
        if cref in visited:
            return
        visited.add(cref)
        obj = resolve_ref(doc, cref)
        if hasattr(obj, 'content_layer'):
            layers.add(obj.content_layer)
        if hasattr(obj, 'children') and obj.children:
            for child in obj.children:
                traverse(child.cref)
    for child in doc.body.children:
        traverse(child.cref)
    print(f, 'layers:', layers)
